function TimerStatus() { const [running, setRunning] = useState(false); useEffect(() => { console.log("Timer status changed"); }, [running]); return ( <button onClick={() => setRunning(value => !value)}> {running ? "Stop" : "Start"} </button> ); }
useState stores the current state.
useEffect reacts to changes in a value to synchronize with an external system or perform a necessary side effect.
